/**
 * Model-metadata enrichment (C4): fills per-model capacity facts the sub2api
 * gateway never reports — context window, max output tokens, image input —
 * from the models.dev catalog (https://models.dev/api.json).
 *
 * Source chain, in order:
 * 1. a fresh catalog fetch (only when `enrichModelMeta` is on), cached
 *    in-process for 24h;
 * 2. the bundled snapshot `data/models-dev.snapshot.json` (generated by
 *    `scripts/fetch-models-dev.mjs`, shipped with the package) — the
 *    deterministic offline fallback;
 * 3. nothing — the caller keeps its route-level defaults.
 *
 * A failed fetch degrades to the bundled snapshot (and is cached as such for
 * the TTL, so an unreachable models.dev is not hammered on every sync).
 * Enrichment never fails a sync.
 *
 * @module sub2api-sync/enrich
 */

import { readFileSync } from 'node:fs'
import { dirname, join } from 'node:path'
import { fileURLToPath } from 'node:url'

/** Per-model capacity facts the enrichment can contribute. */
export interface ModelMeta {
  contextWindow?: number
  maxTokens?: number
  imageInput?: boolean
  reasoningModel?: boolean
}

/** Model id (lowercase) → metadata. */
export type ModelMetaIndex = Map<string, ModelMeta>

const SNAPSHOT_PATH = join(dirname(fileURLToPath(import.meta.url)), '../data/models-dev.snapshot.json')
const SOURCE_URL = 'https://models.dev/api.json'
const TTL = 24 * 60 * 60 * 1000

interface Cache {
  index: ModelMetaIndex
  at: number
}

let networkCache: Cache | undefined
let bundledCache: ModelMetaIndex | undefined

/**
 * Parse the bundled tuple snapshot:
 * `{ generatedAt, source, models: { [id]: [context, output, image, reasoning] } }`.
 */
export function parseSnapshot(raw: string): ModelMetaIndex {
  const index: ModelMetaIndex = new Map()
  let parsed: { models?: Record<string, unknown> } | null | undefined
  try {
    parsed = JSON.parse(raw) as { models?: Record<string, unknown> } | null | undefined
  } catch {
    return index
  }
  const models = parsed?.models
  if (models === null || models === undefined || typeof models !== 'object') return index
  for (const [id, tuple] of Object.entries(models)) {
    if (!Array.isArray(tuple)) continue
    const [context, output, image, reasoning] = tuple as unknown[]
    index.set(id.toLowerCase(), {
      ...(typeof context === 'number' && context > 0 ? { contextWindow: context } : {}),
      ...(typeof output === 'number' && output > 0 ? { maxTokens: output } : {}),
      ...(image === 1 ? { imageInput: true } : {}),
      ...(reasoning === 1 ? { reasoningModel: true } : {}),
    })
  }
  return index
}

/**
 * Parse the live models.dev catalog: `{ [provider]: { models: { [id]: {
 * limit?: { context?, output? }, modalities?: { input?: string[] },
 * attachment?: boolean, reasoning?: boolean } } } }`. The same id under
 * several providers merges with max(context), max(output), OR(image),
 * OR(reasoning).
 */
export function parseCatalog(catalog: unknown): ModelMetaIndex {
  const index: ModelMetaIndex = new Map()
  if (catalog === null || typeof catalog !== 'object') return index
  for (const provider of Object.values(catalog as Record<string, unknown>)) {
    if (provider === null || typeof provider !== 'object') continue
    const models = (provider as Record<string, unknown>).models
    if (models === null || typeof models !== 'object') continue
    for (const [id, raw] of Object.entries(models as Record<string, unknown>)) {
      if (raw === null || typeof raw !== 'object') continue
      const model = raw as Record<string, unknown>
      const limit = (model.limit ?? undefined) as Record<string, unknown> | undefined
      const modalities = (model.modalities ?? undefined) as Record<string, unknown> | undefined
      const context = limit?.context
      const output = limit?.output
      const input = modalities?.input
      const image = (Array.isArray(input) && input.includes('image')) || model.attachment === true
      const key = id.toLowerCase()
      const current = index.get(key)
      const next: ModelMeta = {
        ...(typeof context === 'number' && context > 0 ? { contextWindow: context } : {}),
        ...(typeof output === 'number' && output > 0 ? { maxTokens: output } : {}),
        ...(image ? { imageInput: true } : {}),
        ...(model.reasoning === true ? { reasoningModel: true } : {}),
      }
      if (current === undefined) {
        if (next.contextWindow !== undefined || next.maxTokens !== undefined || next.imageInput === true || next.reasoningModel === true) {
          index.set(key, next)
        }
        continue
      }
      index.set(key, {
        contextWindow: pickGreater(current.contextWindow, next.contextWindow),
        maxTokens: pickGreater(current.maxTokens, next.maxTokens),
        imageInput: current.imageInput === true || next.imageInput === true,
        reasoningModel: current.reasoningModel === true || next.reasoningModel === true,
      })
    }
  }
  return index
}

function pickGreater(a: number | undefined, b: number | undefined): number | undefined {
  if (a === undefined) return b
  if (b === undefined) return a
  return Math.max(a, b)
}

/** The bundled offline snapshot, read once per process. */
export function bundledIndex(): ModelMetaIndex {
  bundledCache ??= (() => {
    try {
      return parseSnapshot(readFileSync(SNAPSHOT_PATH, 'utf8'))
    } catch {
      // A deployment without the data file (trimmed package) enriches nothing.
      return new Map()
    }
  })()
  return bundledCache
}

/**
 * Resolve the index for one sync run. With `enrich` on, a fresh fetch is
 * attempted and cached for 24h (failures degrade to the bundled snapshot and
 * are cached for the same TTL so a dead endpoint is not retried per sync);
 * with `enrich` off, only the bundled snapshot is used — deterministic and
 * offline.
 */
export async function loadModelIndex(options: { enrich: boolean; fetchImpl?: typeof fetch; now?: () => number }): Promise<ModelMetaIndex> {
  const now = (options.now ?? Date.now)()
  if (networkCache !== undefined && now - networkCache.at < TTL) return networkCache.index
  if (options.enrich) {
    try {
      const doFetch = options.fetchImpl ?? globalThis.fetch
      if (doFetch === undefined) throw new Error('no fetch available')
      const response = await doFetch(SOURCE_URL)
      if (!response.ok) throw new Error(`HTTP ${response.status}`)
      const catalog: unknown = await response.json()
      const index = parseCatalog(catalog)
      networkCache = { index, at: now }
      return index
    } catch {
      // Fall through to the bundled snapshot; cached below for the TTL.
    }
  }
  const bundled = bundledIndex()
  if (options.enrich) networkCache = { index: bundled, at: now }
  return bundled
}

/** Test/reset hook: forget the in-process caches. */
export function resetCaches(): void {
  networkCache = undefined
  bundledCache = undefined
}
